export interface InkwellMonogramProps {
  size?: number;
  className?: string;
  title?: string;
  bold?: boolean;
  waxColor?: string;
  strokeColor?: string;
  glyphColor?: string;
  'aria-hidden'?: boolean;
}

export const InkwellMonogram: React.FC<InkwellMonogramProps> = ({
  size = 28,
  className,
  title,
  bold = size < 24,
  waxColor = '#b8231c',
  strokeColor = '#8e1712',
  glyphColor = '#f6e7d2',
  'aria-hidden': ariaHidden,
}) => {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 64 64"
      fill="none"
      className={className}
      role={title ? 'img' : undefined}
      aria-label={title}
      aria-hidden={ariaHidden ?? !title}
    >
      {title ? <title>{title}</title> : null}
      {/* Wax seal outer body */}
      <path
        d={WAX_OUTER_PATH}
        fill={waxColor}
        stroke={strokeColor}
        strokeWidth={1.2}
      />
      {/* Concentric bezel ring with specular lighting */}
      {!bold && (
        <>
          <circle
            cx={32}
            cy={32}
            r={19.5}
            stroke={strokeColor}
            strokeWidth={1.6}
            opacity={0.55}
          />
          <circle
            cx={32}
            cy={32.8}
            r={19.5}
            stroke="#ef6a52"
            strokeWidth={1}
            opacity={0.35}
          />
        </>
      )}
      {/* Intaglio Serif 'I' Monogram */}
      <path
        d={INTAGLIO_SERIF_I_PATH}
        fill={glyphColor}
        stroke={glyphColor}
        strokeWidth={bold ? 2.2 : 1.1}
        strokeLinejoin="round"
      />
    </svg>
  );
};

export default InkwellMonogram;

